const rnd = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
const pick = arr => arr[Math.floor(Math.random() * arr.length)];
function pickW(items, wf){
  const w = items.map(wf); const tot = w.reduce((a,b) => a + b, 0);
  let u = Math.random() * tot;
  for (let i = 0; i < items.length; i++){ u -= w[i]; if (u <= 0) return {item:items[i], prob:w[i]/tot}; }
  return {item:items[items.length-1], prob:w[w.length-1]/tot};
}
function shuffle(a){ for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
function fmtOneIn(p){
  const n = 1 / p;
  if (n >= 1e8) return (n/1e8).toFixed(1).replace(/\.0$/,'') + '億';
  if (n >= 1e5) return Math.round(n/1e4) + '万';
  if (n >= 1e4) return (n/1e4).toFixed(1).replace(/\.0$/,'') + '万';
  if (n >= 100) return Math.round(n).toLocaleString('ja-JP');
  return n.toFixed(n < 10 ? 1 : 0).replace(/\.0$/,'');
}
function eligible(as, sex){
  const s = (as || '').toLowerCase();
  const fillyOnly = /\bf(\/m)?$/.test(s) && !/c/.test(s);
  const coltOnly = /\bc(\/g)?$/.test(s) && !/f/.test(s);
  return sex === 'M' ? !fillyOnly : !coltOnly;
}
function ageFrom(as){
  const m = (as || '').match(/^(\d)(yo|up)/);
  if (!m) return rnd(3,5);
  const a = +m[1];
  return m[2] === 'yo' ? a : rnd(a, a + 2);
}

