/* ---------- 競走馬の枝分かれ ---------- */
function decideRacing(c){
  if (c.id === 'IRL'){
    const r = Math.random();
    if (r < 0.60) return {rc:BYID.GBR, prob:0.60};
    if (r < 0.72){ const t = pickW([['USA',40],['FRA',35],['AUS',25]], x => x[1]); return {rc:BYID[t.item[0]], prob:0.12*t.prob}; }
    return {rc:c, prob:0.28};
  }
  if (c.id === 'GBR'){
    if (Math.random() < 0.25){ const t = pickW([['USA',40],['FRA',25],['AUS',20],['ARE',15]], x => x[1]); return {rc:BYID[t.item[0]], prob:0.25*t.prob}; }
    return {rc:c, prob:0.75};
  }
  if (c.id === 'NZL'){
    if (Math.random() < 0.5) return {rc:BYID.AUS, prob:0.5};
    return {rc:c, prob:0.5};
  }
  return {rc:c, prob:1};
}
function tbTier(rc, mult){
  mult = mult || 1;
  const R = RACES[rc.id], F = F_EFF[rc.id];
  const order = ['g1','g2','g3','l'];
  const pr = {}; order.forEach(k => pr[k] = Math.min(R[k].length / F * mult, 0.4));
  const capSum = 0.28 + (mult > 1 ? Math.min(0.12, (mult - 1) * 0.03) : 0);
  const sum = order.reduce((a,k) => a + pr[k], 0);
  if (sum > capSum) order.forEach(k => pr[k] *= capSum / sum);
  const top = order.reduce((a,k) => a + pr[k], 0);
  const pWin = Math.min(0.62, P_WIN * (1 + (mult - 1) * 0.12));
  const pDebut = Math.min(0.95, P_DEBUT + (pWin - P_WIN) * 0.5);
  let u = Math.random(), acc = 0;
  for (const k of order){ acc += pr[k]; if (u < acc) return {t:k, prob:pr[k]}; }
  if (u < pWin) return {t:'win', prob:pWin - top};
  if (u < pDebut) return {t:'lose', prob:pDebut - pWin};
  return {t:'none', prob:1 - pDebut};
}
// 競走成績の筋書き(スロット = 年齢×2 + 春0/秋1)
function planCareer(rc, sex, mult){
  const tr = tbTier(rc, mult);
  const o = {tier:tr.t, prob:tr.prob, pick:1, d:null, w:null, t:null, f:null, l:null, r:null, race:null, rc:rc};
  if (['g1','g2','g3','l'].includes(tr.t)){
    const all = RACES[rc.id][tr.t]; const pool = all.filter(x => eligible(x[1], sex));
    const use = pool.length ? pool : all; o.race = pick(use); o.pick = 1 / use.length;
    const ag = ageFrom(o.race[1]);
    o.t = ag <= 2 ? 5 : Math.min(ag * 2 + rnd(0,1), 15);
    if (o.t <= 5){ o.d = 4; } else { o.w = Math.max(5, o.t - rnd(1,3)); if (o.w >= o.t) o.w = o.t - 1; o.d = Math.max(4, o.w - rnd(1,2)); }
    o.r = Math.min(17, o.t + rnd(2,5)); if (o.r <= o.t) o.r = o.t + 1;
  } else if (tr.t === 'win'){
    o.d = 5 + rnd(0,1); o.w = o.d + rnd(1,5); o.r = Math.min(17, o.w + rnd(2,6)); if (o.r <= o.w) o.r = o.w + 1;
  } else if (tr.t === 'lose'){
    o.d = 5 + rnd(0,1); o.l = o.d + rnd(2,6); o.r = Math.min(17, o.l + rnd(1,3)); if (o.r <= o.l) o.r = o.l + 1;
  } else { o.f = 6 + rnd(0,3); o.r = o.f + rnd(1,2); }
  return o;
}
const GRADE_JA = {g1:'G1', g2:'G2', g3:'G3', l:'リステッド競走'};
const TIER_RANK = ['none','lose','win','l','g3','g2','g1'];

// 繁殖牝馬: 毎年(春)に仔を産み、仔ごとの成績を母の年表に書き込む
function broodKids(c, tier, r, end, stats){
  const mult = PARENT_Q[tier] || 1; const lines = [];
  let s = r + 2; if (s % 2) s++;
  let n = 0;
  for (; s < end && Math.floor(s / 2) <= 18; s += 2){
    if (Math.random() > 0.85) continue;
    n++;
    const fs = Math.random() < 0.5 ? 'M' : 'F';
    lines.push({slot:s, text:`第${n}仔(${fs==='M'?'牡':'牝'})が生まれた。`});
    const frp = decideRacing(c); const fp = planCareer(frp.rc, fs, mult);
    stats.n++;
    const at = x => s + x;
    let res = null, hit = false;
    if (fp.race){ res = {slot:at(fp.t), text:`第${n}仔が${frp.rc.ja}で${GRADE_JA[fp.tier]}「${fp.race[0]}」を勝った。`}; hit = fp.tier !== 'l';
      stats.win++; if (fp.tier==='l') stats.listed++; else stats.stakes++; if (fp.tier==='g1') stats.g1++;
      stats.notable.push(`第${n}仔: ${frp.rc.ja}の${GRADE_JA[fp.tier]}「${fp.race[0]}」`); }
    else if (fp.tier === 'win'){ res = {slot:at(fp.w), text:`第${n}仔が初勝利を挙げた。`}; stats.win++; }
    else if (fp.tier === 'lose'){ res = {slot:at(fp.l), text:`第${n}仔は勝ち星なく引退した。`}; }
    else { res = {slot:at(fp.f), text:`第${n}仔は故障もあり、一度も走れなかった。`}; }
    if (res && res.slot < end) lines.push({slot:res.slot, text:res.text, hit, cut: fp.race ? {level:{g1:3,g2:2,g3:1,l:1}[fp.tier], kind:['g1','g2','g3'].includes(fp.tier) ? '3d' : '2d', title:'仔の' + (fp.tier === 'l' ? 'リステッド' : GRADE_JA[fp.tier]) + '勝利!', sub:`${frp.rc.ja}｜${fp.race[0]}`} : null});
  }
  return lines;
}
// 種牡馬: 毎年(春)に産駒の世代が生まれ、数年後にその世代の成績がまとまる
function stallionKids(c, tier, r, end, stats){
  const mult = PARENT_Q[tier] || 1; const lines = [];
  const sizeBy = {g1:[90,170], g2:[60,120], g3:[40,90], l:[20,50], win:[8,30], lose:[3,15], none:[2,10]}[tier];
  let s = r + 2; if (s % 2) s++;
  let crop = 0;
  for (; s < end && Math.floor(s / 2) <= 20; s += 2){
    crop++;
    const n = rnd(sizeBy[0], sizeBy[1]);
    lines.push({slot:s, text:`第${crop}世代の産駒(${n}頭)が生まれた。`});
    let win = 0, stakes = 0, g1 = 0, best = 'none', bestRc = null;
    for (let i = 0; i < n; i++){
      const frp = decideRacing(c); const tr = tbTier(frp.rc, mult);
      if (['win','l','g3','g2','g1'].includes(tr.t)) win++;
      if (['g3','g2','g1'].includes(tr.t)) stakes++;
      if (tr.t === 'g1') g1++;
      if (TIER_RANK.indexOf(tr.t) > TIER_RANK.indexOf(best)){ best = tr.t; bestRc = frp.rc; }
    }
    stats.n += n; stats.win += win; stats.stakes += stakes; stats.g1 += g1;
    let tail = '';
    if (['g1','g2','g3','l'].includes(best)){
      const all = RACES[bestRc.id][best]; const rc2 = pick(all);
      tail = `最高成績は${bestRc.ja}の${GRADE_JA[best]}「${rc2[0]}」。`;
      if (best !== 'l') stats.notable.push(`第${crop}世代: ${bestRc.ja}の${GRADE_JA[best]}「${rc2[0]}」`);
    }
    const slot = s + 6;
    if (slot < end) lines.push({slot, text:`第${crop}世代の成績がまとまった。勝ち上がり${win}頭、重賞馬${stakes}頭${g1 ? '(うちG1馬' + g1 + '頭)' : ''}。${tail}`, hit: stakes > 0});
  }
  return lines;
}

const slotInfo = s => ({age:Math.floor(s/2), season: s % 2 ? '秋' : '春'});
function setSlot(E, s, o){ E[s] = Object.assign(slotInfo(s), o); }

const TIER_HEAD = {g1:'G1馬', g2:'G2馬', g3:'G3馬', l:'リステッド馬', win:'勝ち上がり馬', lose:'未勝利馬', none:'未出走馬'};
const TIER_WIN = {g1:'G1勝利', g2:'G2勝利', g3:'G3勝利', l:'リステッド勝ち'};

function newLife(forceTB, parent){
  let p = 1;
  const gen = parent ? (parent.gen || 1) + 1 : 1;
  const cp = parent ? {item: parent.c} : pickW(COUNTRIES, c => forceTB ? c.tb : c.total + c.tb * (TBX - 1)); const c = cp.item;
  if (!parent) p *= c.total / SUM;                                       // 表示する確率は統計どおり
  const sex = Math.random() < 0.5 ? 'M' : 'F';
  const sexJa = sex === 'M' ? '牡馬' : '牝馬';
  const coat = pickW(COATS, x => x[1]).item[0];
  const pTBsample = TBX * c.tb / (TBX * c.tb + (c.total - c.tb));
  const isTB = (forceTB || parent) ? true : Math.random() < pTBsample;
  if (!parent) p *= isTB ? c.tb / c.total : 1 - c.tb / c.total;
  const lifespan = rnd(22, 31);
  const deck = makeDeck(); const E = [];
  const chips = [c.ja];
  if (parent) chips.push(gen + '代目');

  if (isTB){
    const rp = decideRacing(c); const rc = rp.rc; p *= rp.prob;
    const plan = planCareer(rc, sex, parent ? (PARENT_Q[parent.tier] || 1) : 1); p *= plan.prob * plan.pick;
    const {d, w, t, f, l, race, tier} = plan;

    setSlot(E, 0, {head:'誕生', text:`${c.ja}の牧場で、${coat}の${sexJa}として生まれた。サラブレッド。パートI国で生まれる馬のうち、約${Math.round(SUM/TBSUM)}頭に1頭だけが、この血統書を持つ。`});
    if (parent) setSlot(E, 0, {head:'誕生', text:`${parent.sex === 'M' ? '父' : '母'}「${parent.horseName || 'ノーネーム'}」(${parent.headline})の仔として、${c.ja}の牧場で、${coat}の${sexJa}として生まれた。${gen}代目のサラブレッド。`});
    setSlot(E, 1, {head:'離乳', text:deck.draw('foal','秋')});
    setSlot(E, 2, {head:POOLS.yearling.head, text:deck.draw('yearling','春')});
    if (rc.id !== c.id) setSlot(E, 3, {head:'海を渡る', text:`${c.ja}生まれだが、${rc.ja}へ輸出されることが決まった。馬運車と飛行機で、長い旅をした。`});
    else setSlot(E, 3, {head:'育成', text:pick(['セリに出され、買い手がついた。','生産牧場に残り、育成が始まった。','育成牧場に移り、馬具に慣れる日々が始まった。'])});
    if (d !== null){
      const direct = (t === 5);
      setSlot(E, d, {head:'デビュー', text: direct ? 'デビュー戦を勝った。2歳の同期のなかで、ひとつ抜けた存在になった。' : `デビュー戦。ゲートが開いて、初めて全力で走った。${rnd(3,14)}着だった。`, hit:direct, cut: direct ? {level:0, title:'デビュー勝ち!', sub:''} : null});
    }
    if (w !== null) setSlot(E, w, {head:'初勝利', text:`${rnd(2,12)}戦目でようやく初勝利。ここまで来られる馬は、3頭に1頭。`, cut:{level:0, title:'初勝利!', sub:''}});
    if (l !== null) setSlot(E, l, {head:'未勝利', text:`${rnd(3,19)}戦走ったが、勝ち星には届かなかった。`});
    if (f !== null) setSlot(E, f, {head:'未出走', text:pick(['デビュー前の調教で脚元に不安が出て、レースには一度も出られなかった。','気性が難しく、ゲート試験を通らないまま時間が過ぎた。','怪我で長い休養に入り、そのままデビューできなかった。'])});
    if (race){
      const nm = race[0];
      const txt = {
        g1:`${rc.ja}のG1「${nm}」を勝った。生まれた国も、血統も、運も、すべてが重なった一日だった。`,
        g2:`${rc.ja}のG2「${nm}」を勝った。重賞ウイナーの仲間入りをした。`,
        g3:`${rc.ja}のG3「${nm}」を勝った。名前が競馬新聞の見出しに載った。`,
        l:`${rc.ja}のリステッド競走「${nm}」を勝った。ここから先は、名前のある馬になった。`
      }[tier];
      setSlot(E, t, {head:TIER_WIN[tier], text:txt, hit:true, cut:{level:{g1:3,g2:2,g3:1,l:1}[tier], kind:['g1','g2','g3'].includes(tier) ? '3d' : '2d', title:TIER_WIN[tier] + '!', sub:`${rc.ja}｜${nm}`}});
      chips.push(`${TIER_WIN[tier].replace('勝利','').replace('勝ち','')}: ${nm}`);
    }
    // ---- 故障・引退・行方不明(令和7年のJRA・地方の登録抹消の実数をもとに) ----
    const top = ['g1','g2','g3'].includes(tier), flop = ['none','lose'].includes(tier);
    const used = new Set([0,1,2,3,4,d,w,l,f,t].filter(x => x !== null && x !== undefined));
    const lastM = Math.max(d || 0, w || 0, l || 0, f || 0, t || 0, 4);
    let r = plan.r, endInj = null, transfer = false;
    if (tier !== 'none' && Math.random() < 0.22 && lastM + 1 < r){ endInj = lastM + 1 + rnd(0, Math.max(0, r - lastM - 2)); r = endInj + 1; }
    if (rc.id === 'JPN' && endInj === null){ transfer = Math.random() < {none:0.75, lose:0.8, win:0.7, l:0.45, g3:0.2, g2:0.1, g1:0.03}[tier]; }
    const rF = transfer ? Math.min(19, r + rnd(2, 8)) : r;
    const jp = rc.id === 'JPN';
    let wts;
    if (transfer) wts = sex === 'F' ? [['riding',47],['brood',9],['died',17],['lost',20]] : [['riding',56],['gelding',4],['died',17],['lost',20]];
    else if (sex === 'F') wts = [['brood', top ? 85 : (['l','win'].includes(tier) ? 55 : 25)], ['riding', 30], ['lost', flop ? (jp ? 5 : 12) : 3], ['died', (flop ? (jp ? 7 : 10) : 3) + (endInj !== null ? 5 : 0)], ['pasture', top ? 15 : 1]];
    else wts = [['stallion', tier==='g1' ? 60 : tier==='g2' ? 40 : tier==='g3' ? 25 : tier==='l' ? 4 : 0.5], ['riding', 45], ['gelding', 8], ['lost', flop ? (jp ? 5 : 12) : 3], ['died', (flop ? (jp ? 7 : 10) : 3) + (endInj !== null ? 5 : 0)], ['pasture', top ? 15 : 1]];
    const path = pickW(wts, x => x[1]).item[0];
    [r, rF].forEach(x => used.add(x));
    if (endInj !== null){
      const part = pick(['右前脚の管骨','左前脚の第1指骨','右後脚の繋骨','左前脚の屈腱','右前脚の種子骨']);
      setSlot(E, endInj, {head:'故障', text:`${part}に重い故障が見つかった。治っても、競走能力は戻らなかった。`}); used.add(endInj);
    }
    const INJ = [
      {w:26, head:'骨折', len:[2,4], texts:['右前脚の管骨を骨折した。ボルトで固定する手術のあと、半年以上の休養になった。','左前脚の第1指骨にひびが入り、休養を余儀なくされた。','剥離骨折が見つかり、完治まで牧場で休むことになった。']},
      {w:14, head:'屈腱炎', len:[3,6], texts:['屈腱炎を発症した。再発しやすい病気で、復帰までは年単位の時間がかかる。','前脚の屈腱に炎症が見つかった。ゆっくり歩くところから、やり直すことになった。']},
      {w:28, head:'跛行', len:[1,2], texts:['レース後に右前脚の跛行(はこう)が見つかり、休養に入った。','脚元に熱が出て、レースを回避した。','調教後に歩様の乱れが見つかり、様子を見ることになった。']},
      {w:10, head:'蹄の不安', len:[1,2], texts:['裂蹄(れってい)で、削蹄と装蹄をやり直した。','蹄の炎症で、しばらく走れなかった。']},
      {w:12, head:'鼻出血', len:[1,2], texts:['レース中に鼻出血を発症した。一定期間は、出走できなくなった。']},
      {w:10, head:'疝痛・発熱', len:[1,1], texts:['疝痛(せんつう)を起こして、数日間つきっきりで看病された。','熱発で調教を休んだ。']}
    ];
    const startRace = (d === null ? 5 : d + 1);
    let nInj = 0;
    for (let s = startRace; s < rF && nInj < 3; s++){
      if (used.has(s)) continue;
      const age = Math.floor(s / 2), pr = Math.min(0.2, 0.11 + 0.01 * Math.max(0, age - 4));
      if (d === null || Math.random() > pr) continue;
      const it = pickW(INJ, x => x.w).item, len = rnd(it.len[0], it.len[1]);
      let ok = true; for (let k = 0; k <= len + 1; k++){ if (used.has(s + k) || s + k >= rF) ok = false; }
      if (!ok) continue;
      setSlot(E, s, {head:'故障', text:`${it.head}: ` + pick(it.texts)}); used.add(s);
      for (let k = 1; k <= len; k++){ setSlot(E, s + k, {head:'休養', text:deck.draw('rehab', (s + k) % 2 ? '秋' : '春')}); used.add(s + k); }
      setSlot(E, s + len + 1, {head:'復帰', text:`復帰戦。${rnd(1, 12)}着だった。`}); used.add(s + len + 1);
      nInj++; s += len + 1;
    }
    if (transfer){
      setSlot(E, r, {head:'転厩', text:'中央競馬の登録を抹消され、地方競馬へ移った。中央の引退馬のおよそ3分の2が、この道を選ぶ。'});
      const lw = (rF - r > 2 && Math.random() < 0.6) ? r + 1 + rnd(0, rF - r - 2) : null;
      for (let s = r + 1; s < rF; s++){
        if (E[s]) continue;
        if (s === lw) setSlot(E, s, {head:'地方で勝利', text:`地方競馬で${rnd(1,6)}勝目を挙げた。`});
        else setSlot(E, s, {head:POOLS.local.head, text:deck.draw('local', s % 2 ? '秋' : '春')});
      }
    }
    const cause = pickW([[0, 55], [1, 15], [2, 30]], x => x[1]).item[0];
    const DEATH = ['レース中に脚を骨折し、予後不良と診断された。安楽死の処置が取られた。', '調教中の事故で、命を落とした。', '疝痛を発症し、手術の甲斐なく亡くなった。'][cause];
    let end;
    if (path === 'died'){
      setSlot(E, rF, {head:'へい死', text:DEATH}); end = rF;
    } else if (path === 'lost'){
      setSlot(E, rF, {head:'登録抹消', text:RET.lost});
      setSlot(E, rF + 1, {head:'行方不明', text:'足取りは途絶え、その後の記録は残っていない。ここで、この馬の物語は途切れる。'}); end = rF + 1;
    } else {
      setSlot(E, rF, {head:'引退', text:RET[path]});
    }
    const preDebut = s => d === null ? s < f : s < d;
    for (let s = 4; s < rF; s++){
      if (E[s]) continue;
      let key;
      if (f !== null && s > f) key = 'rehab';
      else if (preDebut(s)) key = 'training';
      else key = tier === 'lose' ? 'racingLose' : 'racing';
      setSlot(E, s, {head:POOLS[key].head, text:deck.draw(key, s % 2 ? '秋' : '春')});
    }
    if (E[4].head === '調教') E[4].head = '入厩';
    const kids = {n:0, win:0, stakes:0, g1:0, listed:0, notable:[]};
    if (path !== 'died' && path !== 'lost'){
      end = lifespan * 2 + 1; if (end <= rF + 2) end = rF + 4;
      for (let s = rF + 1; s < end; s++){
        const age = Math.floor(s / 2);
        const key = age >= 19 ? 'old' : path;
        setSlot(E, s, {head:POOLS[key].head, text:deck.draw(key, s % 2 ? '秋' : '春')});
      }
      setSlot(E, end, {head:'最期', text:pick(LIFE_END)});
      const klines = path === 'brood' ? broodKids(c, tier, rF, end, kids) : path === 'stallion' ? stallionKids(c, tier, rF, end, kids) : [];
      klines.forEach(k => { const e = E[k.slot]; if (!e) return; (e.kids = e.kids || []).push({text:k.text, hit:!!k.hit}); if (k.hit) e.hit = true; if (k.cut && !e.cut) e.cut = k.cut; });
    }
    const steps = E.filter(Boolean);
    let sub = race ? `「${race[0]}」の勝ち馬` : ({win:'1勝を挙げた', lose:'勝てないまま引退した', none:'レースを一度も走らなかった'}[tier] || '');
    if (path === 'died') { sub += '(競走生活の途中で亡くなった)'; chips.push('へい死'); }
    if (path === 'lost') { sub += '(引退後の行方は不明)'; chips.push('行方不明'); }
    if (transfer) chips.push('地方へ転厩');
    if (kids.n > 0) chips.push(`${path === 'brood' ? '産んだ仔' : '産駒'}${kids.n}頭`);
    return {steps, p, c, isTB:true, headline:TIER_HEAD[tier], sub, chips, sex, breed:'サラブレッド', kids, path, coat, tier, rc, transfer, gen,
      lineage: parent ? (parent.lineage || []).concat([{n: parent.horseName || 'ノーネーム', sx: parent.sex, h: parent.headline}]).slice(-4) : []};
  }

  // サラブレッド以外
  const prof = c.id === 'JPN' ? [['banei',88],['riding',12]] : [['work',55],['riding',30],['pony',15]];
  const kp = pickW(prof, x => x[1]); p *= kp.prob; const cls = NONTB[kp.item[0]];
  const op = pickW(cls.outcomes, o => o.w); p *= op.prob;
  chips.push(cls.name);
  setSlot(E, 0, {head:'誕生', text:`${c.ja}で、${coat}の${sexJa}として生まれた。サラブレッドではなく、${cls.name}の血筋。パートI国の馬の約${Math.round(SUM/TBSUM)}頭に${Math.round(SUM/TBSUM)-1}頭は、こちら側に生まれる。`});
  setSlot(E, 1, {head:'離乳', text:deck.draw('foal','秋')});
  setSlot(E, 2, {head:POOLS.yearling.head, text:deck.draw('yearling','春')});
  setSlot(E, 3, {head:POOLS.yearling.head, text:deck.draw('yearling','秋')});
  setSlot(E, 4, {head:'仕事を覚える', text:'人を乗せ、荷を引き、ひとつずつ仕事を覚えていった。'});
  const end = lifespan * 2 + 1;
  const m = 8 + rnd(0, 6);
  setSlot(E, m, {head:op.item.tag, text:pick(op.item.text), hit:!!op.item.hit});
  for (let s = 5; s < end; s++){
    if (E[s]) continue;
    const age = Math.floor(s / 2);
    const key = age >= 19 ? 'old' : cls.years;
    setSlot(E, s, {head:POOLS[key].head, text:deck.draw(key, s % 2 ? '秋' : '春')});
  }
  setSlot(E, end, {head:'最期', text:pick(LIFE_END)});
  return {steps:E.filter(Boolean), p, c, isTB:false, headline:cls.name, sub:op.item.tag, chips, sex, breed:cls.name, coat, gen:1, lineage:[]};
}

function rarityOf(life){
  const h = life.headline;
  if (h === 'G1馬') return 'g1'; if (h === 'G2馬') return 'g2'; if (h === 'G3馬') return 'g3'; if (h === 'リステッド馬') return 'l';
  if (!life.isTB && ['国内大会で上位','国際大会','ばんえい競走馬'].includes(life.sub)) return 'l';
  return 'n';
}
